package run.ikaros.password; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class PasswordHistoryService{private final PasswordVaultItemRepository items;private final PasswordHistoryRepository history;public PasswordHistoryService(PasswordVaultItemRepository i,PasswordHistoryRepository h){items=i;history=h;}public Mono<PasswordHistoryView> record(UUID a,UUID itemId,RecordPasswordHistoryRequest q){return items.findById(itemId).filter(i->i.ownerId().equals(a)&&!i.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).flatMap(i->history.save(new PasswordHistoryEntity(null,itemId,i.vaultId(),a,q.revision(),q.encryptedPayload(),Instant.now()))).map(this::view);}public Flux<PasswordHistoryView> list(UUID a,UUID itemId){return items.findById(itemId).filter(i->i.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Vault Item 不存在或无权访问"))).flatMapMany(i->history.findAllByItemIdAndOwnerIdOrderByRevisionDesc(itemId,a).map(this::view));}private PasswordHistoryView view(PasswordHistoryEntity h){return new PasswordHistoryView(h.id(),h.itemId(),h.revision(),h.encryptedPayload(),h.createdAt());}}
